let D=null, view='dashboard', lang=localStorage.getItem('hynak_language')||'zh', search='', page=1, filterStatus='', formKey='', formSubmit=null, collectionFilter={}, brazilLocations=null;
const $=s=>document.querySelector(s), E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const L=(zh,pt,en)=>lang==='pt'?pt:lang==='en'?en:zh;
