const labels={dashboard:['业务概览','Visão geral','Overview'],orders:['订单','Pedidos','Orders'],products:['商品与价格','Produtos e preços','Products & prices'],dealers:['经销商','Revendedores','Dealers'],inventory:['库存与寄售','Estoque e consignação','Inventory'],finance:['应收与实收','Contas a receber','Finance'],collections:['回款跟进','Cobranças','Collections'],commissions:['销售佣金','Comissões','Commissions'],data:['数据导入 / 导出','Importar / exportar','Data import / export'],users:['账号与权限','Usuários e acesso','Users & access'],audit:['操作日志','Auditoria','Audit log']};
