const badge=s=>`<span class="badge ${['PAID','CLOSED','CONFIRMED','VERIFIED','APPROVED','DELIVERED','COMMITTED'].includes(s)?'green':['OVERDUE','REJECTED','CANCELED','EXPIRED','RETURNED'].includes(s)?'red':'amber'}">${E(st(s))}</span>`;
