function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';setTimeout(()=>el.style.display='none',5000)}
async function api(path,body,method='POST',key){const headers={};if(body!==undefined&&!(body instanceof FormData))headers['Content-Type']='application/json';if(D)headers['X-CSRF-Token']=D.csrf;if(path.startsWith('/api/action/')||path.startsWith('/api/orders'))headers['Idempotency-Key']=key||crypto.randomUUID();const r=await fetch(path,{method:body===undefined?'GET':method,headers,body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});let j;try{j=await r.json()}catch{throw Error('HTTP '+r.status)}if(!r.ok){if(r.status===401&&D)location.reload();throw Error(j.detail||'HTTP '+r.status)}return j}
async function load(){D=await api('/api/data');render()}
const head=(name,subtitle,actions='')=>`<div class="page-heading"><div><div class="eyebrow">HYNAK / ${E(title(name))}</div><h1>${E(title(name))}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const panel=(name,body,actions='')=>`<section class="panel"><div class="panel-head"><h2>${name}</h2>${actions}</div>${body}</section>`;
const simpleTable=(cols,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c[1](r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();
function table(cols,rows,statusesList=[]){const filtered=rows.filter(r=>(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()))&&(!filterStatus||r.status===filterStatus||r.payment_status===filterStatus));const max=Math.max(1,Math.ceil(filtered.length/12));page=Math.min(page,max);return `<div class="toolbar"><input id="table-search" placeholder="${L('搜索记录…','Buscar registros…','Search records…')}" value="${E(search)}">${statusesList.length?`<select id="status-filter"><option value="">${L('全部状态','Todos os status','All statuses')}</option>${statusesList.map(s=>`<option value="${s}" ${filterStatus===s?'selected':''}>${E(st(s))}</option>`).join('')}</select>`:''}<span class="muted">${filtered.length} ${L('条记录','registros','records')}</span></div>${simpleTable(cols,filtered.slice((page-1)*12,page*12))}<div class="pager"><span>${page} / ${max}</span><div class="actions">${button('prev','←','','small')}${button('next','→',max,'small')}</div></div>`}
function metric(name,value,sub=''){return `<div class="metric"><span class="dot"></span><div class="muted">${name}</div><div class="value numeric">${value}</div><div class="mini">${sub||'BRL · R$'}</div></div>`}
function shell(body){const keys=['dashboard','orders','products','dealers','inventory',...(is('admin','finance','sales','dealer')?['finance']:[]),...(is('admin','finance','sales')?['collections','commissions']:[]),'data',...(is('admin')?['users','audit']:[])];const icons=['◫','▤','◇','♧','▦','◉','↗','%','⇅','⚙','≡'];return `<div class="shell"><aside class="sidebar"><div class="brand">HYNAK</div><div class="brand-note">MOBILITY · BUSINESS</div><nav class="nav">${keys.map((k,i)=>button('nav',`<span class="icon">${icons[i]}</span>${E(title(k))}`,k,view===k?'active':'')).join('')}</nav><div class="sidebar-footer">${L('巴西业务工作台','Workspace Brasil','Brazil business workspace')}<span class="role">${E(D.user.name)} · ${E(D.user.role)}</span></div></aside><main class="main"><header class="topbar"><span class="eyebrow">${L('销售 · 库存 · 回款','Vendas · Estoque · Recebimentos','Sales · Inventory · Receipts')}</span><div class="top-actions"><select id="language" aria-label="Language"><option value="zh" ${lang==='zh'?'selected':''}>简体中文</option><option value="pt" ${lang==='pt'?'selected':''}>Português</option><option value="en" ${lang==='en'?'selected':''}>English</option></select><span class="avatar">${E(D.user.name.slice(0,1))}</span>${button('logout',L('退出','Sair','Sign out'),'','small')}</div></header><div class="content">${testNotice()}${body}</div></main></div>`}
