function f(name,label,type='text',value='',required=true,extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${E(value)}" ${required?'required':''} ${extra}></div>`}
function sel(name,label,options,value='',required=true){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${required?'required':''}><option value="">—</option>${options.map(o=>`<option value="${E(o[0])}" ${String(o[0])===String(value)?'selected':''}>${E(o[1])}</option>`).join('')}</select></div>`}
function ta(name,label,value='',required=false){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${required?'required':''}>${E(value)}</textarea></div>`}
function check(name,label,value=false){return `<div class="check"><input type="checkbox" id="f-${name}" name="${name}" ${value?'checked':''}><label for="f-${name}">${label}</label></div>`}
const dealerOpts=()=>D.dealers.map(d=>[d.id,d.name]),salesOpts=()=>D.users.filter(u=>u.role==='sales').map(u=>[u.id,u.name]),prodOpts=()=>D.products.filter(p=>p.active).map(p=>[p.id,`${p.sku} · ${p.name} · ${money(p.price)}`]),wareOpts=()=>D.warehouses.map(w=>[w.id,`${w.name} · ${w.kind}`]),orderOpts=()=>D.orders.filter(o=>o.outstanding>0).map(o=>[o.id,`${o.number} · ${o.dealer} · ${money(o.outstanding)}`]);
function modal(name,body,submit,submitText){formKey=crypto.randomUUID();formSubmit=submit;$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${name}</h2>${button('close','×')}</div><form id="dialog-form"><div class="dialog-body">${body}<div class="form-error" role="alert"></div></div><div class="dialog-footer">${button('close',L('关闭','Fechar','Close'))}${submit?`<button class="primary" type="submit">${submitText||L('保存','Salvar','Save')}</button>`:''}</div></form>`;$('#modal').showModal()}
function values(){const form=$('#dialog-form'),out=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(c=>out[c.name]=c.checked);return out}
async function action(name,payload){return api('/api/action/'+name,payload,'POST',formKey)}
function lineEditor(line){return `<div class="line-editor"><div><label>SKU</label><select class="line-product" required>${prodOpts().map(p=>`<option value="${p[0]}" ${p[0]===line?.product_id?'selected':''}>${E(p[1])}</option>`).join('')}</select></div><div><label>${L('数量','Qtd.','Qty')}</label><input class="line-qty" type="number" min="1" max="1000000" step="1" value="${line?.quantity||1}" required></div><div><label>${L('自定单价(仅管理员)','Preço (admin)','Override (admin)')}</label><input class="line-price" type="number" min="0" step="0.01" ${is('admin')?'':'disabled'} value="" placeholder="${line?amt(line.unit_price):'—'}"></div>${button('removeline','×','','small')}</div>`}
function orderItems(){return [...document.querySelectorAll('.line-editor')].map(el=>({product_id:Number(el.querySelector('.line-product').value),quantity:el.querySelector('.line-qty').value,unit_price:el.querySelector('.line-price').value||undefined}))}
const citySearchKey=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
const formatCnpj=x=>{const raw=String(x||'').replace(/[.\s/\-]/g,'').toUpperCase();return /^[A-Z0-9]{12}[0-9]{2}$/.test(raw)?raw.replace(/^(.{2})(.{3})(.{3})(.{4})(.{2})$/,'$1.$2.$3/$4-$5'):String(x||'')};
const formatCep=x=>/^[0-9]{8}$/.test(String(x||''))?String(x).slice(0,5)+'-'+String(x).slice(5):String(x||'');
function dealerCityOptions(reset=false){
const state=$('#f-address_state'),city=$('#f-address_city_id'),searchField=$('#city-search');
if(!state||!city)return;
const current=reset?'':city.value;
if(reset&&searchField)searchField.value='';
const query=citySearchKey(searchField?.value.trim());
const cities=brazilLocations?.cities[state.value]||[];
city.innerHTML=`<option value="">${L('请选择城市','Selecione o município','Choose city')}</option>`+cities.filter(c=>c.id===current||!query||citySearchKey(c.name).includes(query)).map(c=>`<option value="${E(c.id)}" ${c.id===current?'selected':''}>${E(c.name)}</option>`).join('');
city.disabled=!state.value;if(searchField)searchField.disabled=!state.value;
syncDealerAddress();
}
function syncDealerAddress(){
const keys=['address_state','address_city_id','address_street','address_number','address_district','address_complement','address_cep'];
const inputs=keys.map(k=>$('#f-'+k));if(inputs.some(el=>!el))return;
const active=inputs.some(el=>el.value.trim());
inputs.forEach(el=>el.required=active&&el.name!=='address_complement');
const val=k=>$('#f-'+k).value.trim(),city=$('#f-address_city_id').selectedOptions[0];
const cityLabel=val('address_city_id')?city?.textContent:'';
const street=[val('address_street'),val('address_number')].filter(Boolean).join(', ');
const lines=[[street,val('address_complement')].filter(Boolean).join(' · '),val('address_district'),[cityLabel,val('address_state')].filter(Boolean).join(' / '),val('address_cep')?'CEP '+formatCep(val('address_cep')):''].filter(Boolean);
$('#address-preview').textContent=lines.length?lines.join('\n'):L('地址预览：先选择州和城市，再填写街道等资料。','Prévia: selecione a UF e o município e preencha o endereço.','Address preview: choose state and city, then enter the street details.');
}
