function syncSaleFields(){
const kind=$('#f-sale_type')?.value, cash=kind==='CASH';
const due=$('#due-fields'), paid=$('#cash-fields');
if(due){due.hidden=cash;due.querySelectorAll('input').forEach(el=>{el.disabled=cash;el.required=!cash})}
if(paid){paid.hidden=!cash;paid.querySelectorAll('input').forEach(el=>{el.disabled=!cash;el.required=cash&&(el.name!=='file'||paid.dataset.hasProof!=='1')})}
}
